fieldCSS:
@import url('https://fonts.googleapis.com/css?family={{FONT}}:100,100i,300,300i,400,400i,500,500i,700,700i,900,900i|{{FONT}}:100,100i,300,300i,400,400i,500,500i,700,700i,900,900i|Montserrat:100,100i,300,300i,400,400i,500,500i,700,700i,900,900i');

  #_builder-form .form-builder--item input[type=text][class=form-control],#_builder-form .form-builder--item .date-picker-custom-style,#_builder-form .form-builder--item input[type=number]{
    background-color: #FFFFFFFF !important;
    color: #000000FF !important;
    border: 1px solid #ACACACFF !important;
    border-radius: 5px !important;
    padding: 12px 15px 10px 20px !important;
    box-shadow: 1px 1px 2px 0px #FFFFFF;
    font-family: '{{FONT}}';
    font-size: 14px;
    font-weight: 500;
    background-clip: inherit !important;
  }
  #_builder-form textarea {
    background-color: #FFFFFFFF !important;
    color: #000000FF !important;
    border: 1px solid #ACACACFF !important;
    border-radius: 5px !important;
    padding: 12px 15px 10px 20px !important;
    box-shadow: 1px 1px 2px 0px #FFFFFF !important;
    font-family: '{{FONT}}';
    font-size: 14px;
    font-weight: 500;
    background-clip: inherit !important;
  }
  #_builder-form input[type=tel],#_builder-form input[type=email],#_builder-form .multiselect .multiselect__tags{
    background-color: #FFFFFFFF !important;
    color: #000000FF !important;
    border: 1px solid #ACACACFF !important;
    border: 1px solid #ACACACFF !important;
    border-radius: 5px !important;
    padding: 12px 15px 10px 20px !important;
    box-shadow: 1px 1px 2px 0px #FFFFFF;
    font-family: '{{FONT}}';
    font-size: 14px;
    font-weight: 500;
    background-clip: inherit !important;
  }
  #_builder-form .multi_select_form {
    border-radius: 5px !important;
  }
  #_builder-form .iti--allow-dropdown input, .iti--allow-dropdown input[type=tel]{
    padding-left: 50px !important;
  }
  #_builder-form .countryphone {
    height: inherit;
  }


  #_builder-form .form-builder--item .date-picker-custom-style input[type=text],  #_builder-form .form-builder--item .multiselect .multiselect__placeholder {
    padding:0;
    background-color: #FFFFFFFF;
    color: #000000FF;
    font-size: 14px;
  }
  #_builder-form .form-builder--item .multiselect .multiselect__input{
    background-color: #FFFFFFFF !important;
  }
  #_builder-form .form-builder--item .multiselect .multiselect__select{
    background: transparent;
    z-index:10;
  }
  #_builder-form .form-builder--item .multiselect ,.multiselect__single{
    padding:0 !important;
    margin:0 !important;
    min-height: 24px;
    color:  #000000FF !important;
    background-color: #FFFFFFFF !important;
    font-family: '{{FONT}}';
    font-size: 14px;
    font-weight: 500;
  }
  #_builder-form .form-builder--item  .multiselect__placeholder {
    padding:0 !important;
    margin:0 !important;
    min-height: 24px;
    color: #8c8c8cFF !important;
    background-color: #FFFFFFFF !important;
    font-family: '{{FONT}}';
    font-size: 14px;
    font-weight: 500;
  }
  #_builder-form .field-container{
    width:100%;
    max-width: 900px;
  }
  #_builder-form ::-webkit-input-placeholder { /* Chrome, Firefox, Opera, Safari 10.1+ */
    color: #8c8c8cFF;
    font-family: '{{FONT}}';
    font-size: 14px;
    font-weight: 500;
    opacity: 1; /* Firefox */
  }
  #_builder-form ::placeholder {
    color: #8c8c8cFF !important;
    font-family: '{{FONT}}';
    font-size: 14px;
    font-weight: 500;
  }
  #_builder-form :-ms-input-placeholder { /* Internet Explorer 10-11 */
    color: #8c8c8cFF !important;
    font-family: '{{FONT}}';
    font-size: 14px;
    font-weight: 500;
  }
  #_builder-form ::-ms-input-placeholder { /* Microsoft Edge */
    color: #8c8c8cFF !important;
    font-family: '{{FONT}}';
    font-size: 14px;
    font-weight: 500;
  }

  #_builder-form label{
    color: #FFFFFFFF;
    font-family: '{{FONT}}';
    font-size: 16px;
    font-weight: 500;
  }
  #_builder-form label * {
    color: #FFFFFFFF;
    font-family: '{{FONT}}';
  }
  #_builder-form .text-element * {
    color: inherit;
    font-family: '{{FONT}}';
  }
  #_builder-form .short-label{
    color: #2c3345FF;
    font-family: '{{FONT}}';
    font-size: 12px;
    font-weight: 300;
    -webkit-font-smoothing: auto;
  }
  #_builder-form .form-builder--item .payment-suggestion-tag-container {
    background-color: #FFFFFFFF;
    color: #000000FF !important;
    font-family: '{{FONT}}';
    font-size: 14px;
    font-weight: 500;
      box-shadow: 1px 1px 2px 0px #FFFFFF;
  }
  #_builder-form .product-summary-amount-large, #order-confirmation .product-summary-amount-large {
    color: #FFFFFFFF;
    font-size: 20px;
    font-weight: 700;
    font-family: {{FONT}};
    line-height: 1.5rem;
  }
  #_builder-form .product-summary-amount-normal, #order-confirmation .product-summary-amount-normal {
    color: #FFFFFFFF;
    font-size: 16px;
    font-weight: 600;
    font-family: {{FONT}};
    line-height: 1.5rem;
  }
  #_builder-form .product-summary-label-bold, #order-confirmation .product-summary-label-bold{
    color: #FFFFFFFF;
    font-size: 16px;
    font-weight: 700;
    font-family: {{FONT}};
    line-height: 1.5rem;
  }
  #_builder-form .crossed-amount {
    color: #FFFFFFFF;
    font-size: 18px;
    font-weight: 600;
    font-family: {{FONT}};
    line-height: 1.5rem;
  }
  #_builder-form .product-summary-label-large, #order-confirmation .product-summary-label-large{
    color: #FFFFFFFF;
    font-size: 18px;
    font-weight: 600;
    font-family: {{FONT}};
    line-height: 1.575rem;
  }
  #_builder-form .product-summary-label-normal, #order-confirmation .product-summary-label-normal{
    color: #FFFFFFFF;
    font-size: 16px;
    font-weight: 500;
    font-family: {{FONT}};
    line-height: 1.575rem;
  }
  #_builder-form .product-summary-label-small, #order-confirmation .product-summary-label-small{
    color: #FFFFFFFF;
    font-size: 14px;
    font-weight: 500;
    font-family: {{FONT}};
    line-height: 1.575rem;
  }
  #_builder-form .variant-tag {
    color: #FFFFFFFF;
    font-size: 15px;
    font-weight: 500;
    font-family: {{FONT}};
    line-height: 1.5rem;
  }
  #_builder-form .selected-tag {
    background-color: #009EF426 !important;
  }
  #_builder-form .payment-tag, #_builder-form .quantity-container-counter {
    box-shadow: 1px 1px 2px 0px #FFFFFF;
    background-color : #FFFFFFFF;
  }
  #_builder-form .quantity-container-counter  {
    padding-top: 10px !important;
    padding-bottom:  8px !important;
  }
  #_builder-form .quantity-text {
    font-size: 14px !important;
  }
  .bubble-label, .bubble-checkbox-label {
    background-color: #FFFFFFFF !important;
    color: #8c8c8cFF !important;
    font-family: '{{FONT}}' !important;
    font-size: 14px !important;
    font-weight: 500 !important;
  }
  .bubble-container, .bubble-checkbox-container {
    border: 1px solid #ACACACFF !important;
    border-radius: 12px !important;
    /* Small horizontal gap between bubbles */
    margin-left: 2px !important;
    margin-right: 2px !important;
    padding: 12px 15px 10px 20px !important;
    box-shadow: 1px 1px 2px 0px #FFFFFF;
    font-family: '{{FONT}}';
    font-size: 16px;
    font-weight: 500;
    background-clip: inherit !important;
  }
  .vdpHeadCellContent {
    word-wrap: normal;
    }

